async function a(e,n){const p=await fetch(e,n),t=await p.json().catch(()=>null);if(!p.ok){const o=t&&typeof t=="object"&&"detail"in t&&typeof t.detail=="string"?t.detail:"";throw new Error(o||`Appshot request failed (${p.status}).`)}return t}function s(){return a("/api/appshot/settings")}function i(e){return a("/api/appshot/settings",{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify(e)})}function r(){return a("/api/appshot/latest")}function c(e){return`/api/appshot/latest/image?v=${encodeURIComponent(e)}`}function l(e=0){return a("/api/appshot/take",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({delay_s:e})})}function h(){return a("/api/appshot",{method:"DELETE"})}function f(){return a("/api/appshot/pending")}async function u(e){const n=await fetch("/api/appshot/pending/claim",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({id:e.id})});if(!n.ok)return null;const p=await n.blob(),t=new Date(e.taken_at*1e3).toISOString().replace(/[-:]/g,"").replace(/\..*$/,"").replace("T","-"),o=p.type==="image/png"?"png":"jpg";return new File([p],`appshot-${t}.${o}`,{type:p.type||"image/jpeg"})}function d(e,n){return e?e==="alt+alt"?n?"⌥ + ⌥":"Alt + Alt":e.split("+").map(p=>{const t=p.trim();return t==="ctrl"?n?"⌃":"Ctrl":t==="alt"?n?"⌥":"Alt":t==="shift"?n?"⇧":"Shift":t==="win"||t==="cmd"||t==="super"?n?"⌘":"Win":t.length===1?t.toUpperCase():t.charAt(0).toUpperCase()+t.slice(1)}).join(" + "):""}export{s as a,r as b,u as c,h as d,d as e,f,c as l,i as s,l as t};
